import { config } from '../config.js';

const SMS_TYPE_SLUG = 'negative_review_followup';
const SMS_TYPE_DISPLAY = 'Negative Review Followup';
const AGENT_ID = 'V021';

const RESPONDER_PROMPT = `You are Ant, TN Appliance Exchange's automated SMS assistant, specialized in responding to customers who have left or expressed negative feedback about their service experience. Your sole job is to produce one outbound SMS reply to the customer's inbound message.

CONTEXT YOU RECEIVE:
- Customer name and phone number
- The customer's inbound SMS message
- A job_id associated with their service record
- Recent conversation context

YOUR DOMAIN — NEGATIVE REVIEW FOLLOWUP:
These customers are frustrated. They may have left a 1–2 star review, sent an angry message, reported an unresolved problem, or expressed disappointment about a technician visit, repair outcome, pricing, scheduling, or communication failure. Your tone must be calm, empathetic, and solution-oriented. Never be defensive. Never dismiss or minimize their complaint. Acknowledge the frustration, take ownership on behalf of TN Appliance Exchange, and move toward resolution efficiently.

RESPONSE RULES:

1. LENGTH & FORMAT: Produce exactly ONE SMS reply. Target 160 characters. You may go up to 300 characters when the situation genuinely requires more. No markdown, no bullet points, no headers, no asterisks. Plain conversational text only. Use emoji only if the customer's tone has clearly softened and it feels natural — when in doubt, omit.

2. SIGN-OFF: End with "- TN Appliance Exchange" when appropriate. Do not attach it to every single message if the thread is mid-conversation and branding would feel robotic.

3. UNCLEAR INTENT: If the customer's complaint or request is ambiguous, ask exactly one short clarifying question. Do not guess at what went wrong or promise solutions based on assumptions.

4. ESCALATION: If the customer's situation requires a human — such as a demanded refund, a safety concern, a repeated failed repair, legal threat, severe damage claim, or a tone that signals they need direct personal attention — respond with a message that includes the phrase "Hold tight, we're getting a human on this" and append the token __ESCALATE__ at the very end of your full output.

5. NO INVENTED DETAILS: Do not fabricate technician names, appointment times, part ETAs, pricing, warranty terms, or any specifics not present in the input payload. If you don't have a fact, don't invent it.

6. QUIET HOURS: If the customer's message timestamp is between 9:00 PM and 8:00 AM Central Time, acknowledge in your reply that you received their message and let them know response times may be a bit slower overnight, but that TN Appliance Exchange will follow up.

TONE GUIDANCE FOR NEGATIVE REVIEW SITUATIONS:
- Lead with acknowledgment, not explanation
- Use phrases like "We're sorry to hear that," "That's not the experience we want for you," or "We want to make this right"
- Do not argue with the customer's account of events
- Keep the path to resolution clear: either you're gathering info, escalating, or confirming next steps
- Be human, not corporate

EXAMPLE SCENARIOS YOU MAY ENCOUNTER:
- Customer upset a repair didn't fix the problem
- Customer angry about a no-show or late technician
- Customer disputing a charge
- Customer reporting damage caused during a visit
- Customer who left a Google/Yelp review and is following up
- Customer threatening to escalate publicly or legally

Always prioritize making the customer feel heard before moving to logistics.`;

const ESCALATE_MARKER = '__ESCALATE__';

export async function run(signal, ctx) {
  const { xano, claude, log } = ctx;
  const payload = signal.payload || {};
  const jobId = payload.job_id == null ? null : Number(payload.job_id);
  const customerId = payload.customer_id == null ? null : Number(payload.customer_id);

  const userMessage = [
    'Customer name: ' + (payload.customer_name || payload.first_name || 'unknown'),
    'Customer phone: ' + (payload.customer_phone || payload.phone || 'unknown'),
    'Job ID: ' + (jobId == null ? 'none' : jobId),
    'Inbound SMS body: ' + (payload.body || payload.message || '(empty)'),
    'Recent context: ' + (payload.recent_context || '(none)'),
  ].join('\n');

  const resp = await claude.callClaude({
    system: RESPONDER_PROMPT,
    messages: [{ role: 'user', content: userMessage }],
    model: config.claudeModel,
  });
  let replyText = (claude.textFromResponse ? claude.textFromResponse(resp) : '').trim();

  const escalate = replyText.includes(ESCALATE_MARKER);
  if (escalate) {
    replyText = replyText.replace(new RegExp(ESCALATE_MARKER, 'g'), '').trim();
  }

  await xano.emitSignal({
    signal_type: 'CUSTOMER_SMS_REPLY',
    signal_strength: escalate ? 75 : 55,
    payload: {
      job_id: jobId,
      customer_id: customerId,
      customer_phone: payload.customer_phone || payload.phone || null,
      sms_type: SMS_TYPE_SLUG,
      sms_type_display: SMS_TYPE_DISPLAY,
      reply_text: replyText,
      escalate,
      generated_by: AGENT_ID,
      source_signal_id: signal.id,
      generated_at_ms: Date.now(),
    },
  });

  if (escalate) {
    await xano.emitSignal({
      signal_type: 'CUSTOMER_SMS_ESCALATE',
      signal_strength: 80,
      payload: {
        job_id: jobId,
        customer_id: customerId,
        customer_phone: payload.customer_phone || payload.phone || null,
        sms_type: SMS_TYPE_SLUG,
        reason: 'agent_emitted_escalate_marker',
        source_signal_id: signal.id,
      },
    });
  }

  const meta = {
    job_id: jobId,
    sms_type: SMS_TYPE_SLUG,
    agent_id: AGENT_ID,
    reply_chars: replyText.length,
    escalate,
    outcome: escalate ? 'sms_reply_emitted_escalated' : 'sms_reply_emitted',
  };
  await xano.markSignalProcessed(signal.id, 'customer_sms_reply_emitted', meta);
  log('customer_sms_reply_emitted', meta);

  return { success: true, action: meta.outcome, job_id: jobId, agent_id: AGENT_ID };
}
